starter.solution.cpp:
int applyTwice(int (*f)(int), int x)
{
    return x;
}

solution.solution.cpp:
int applyTwice(int (*f)(int), int x)
{
    return f(f(x));
}

unitTests:
int addThree(int n) { return n + 3; }
int doubleIt(int n) { return n * 2; }
int negate(int n) { return -n; }
TEST("adding three twice") { CHECK_EQ(applyTwice(addThree, 10), 16); }
TEST("doubling twice") { CHECK_EQ(applyTwice(doubleIt, 5), 20); }
TEST("negating twice changes nothing") { CHECK_EQ(applyTwice(negate, 7), 7); }
TEST("a lambda without captures works too") { CHECK_EQ(applyTwice([](int n) { return n * n; }, 3), 81); }

